// weft_board_top: gatemate-a1-evb board top for the Weft design lights (generated by weft; do not edit).
// Clock clk_10m (10 MHz) feeds the main domain; active-low pins are inverted here, so the design sees
// active-high levels; physical inputs pass a two-flop synchronizer in their domain.
module weft_board_top (
  input  wire clk_10m,
  input  wire pin_btn_0,
  output wire pin_led_0,
  output wire pin_led_1,
  output wire pin_led_2,
  output wire pin_led_3,
  output wire pin_led_4,
  output wire pin_led_5,
  output wire pin_led_6,
  output wire pin_led_7,
  output wire pin_uart_tx,
  input  wire pin_uart_rx
);
  wire usr_rstn;
  CC_USR_RSTN u_usr_rstn (.USR_RSTN(usr_rstn));
  wire rst_req = ~usr_rstn;
  reg [1:0] rst_sync = 2'b11;
  always @(posedge clk_10m or posedge rst_req)
    if (rst_req) rst_sync <= 2'b11; else rst_sync <= {rst_sync[0], 1'b0};
  wire rst_cfg = rst_sync[1];
  wire hil_rst;                      // the bridge's R command
  wire rst = rst_cfg | hil_rst;
  wire [4:0] hil_vins, hil_ovr;
  wire pin_sw_0_lvl = hil_vins[0];  // sw:0 is virtual: the bridge drives it
  wire pin_btn_0_lvl = hil_ovr[1] ? hil_vins[1] : ~pin_btn_0;
  wire pin_btn_1_lvl = hil_vins[2];  // btn:1 is virtual: the bridge drives it
  wire pin_btn_2_lvl = hil_vins[3];  // btn:2 is virtual: the bridge drives it
  wire pin_btn_3_lvl = hil_vins[4];  // btn:3 is virtual: the bridge drives it
  wire [0:0] d_sw;
  reg [1:0] hs_sw_0 = 2'b00;
  always @(posedge clk_10m) hs_sw_0 <= {hs_sw_0[0], pin_sw_0_lvl};
  assign d_sw[0] = hs_sw_0[1];
  wire [3:0] d_btn;
  reg [1:0] hs_btn_0 = 2'b00;
  always @(posedge clk_10m) hs_btn_0 <= {hs_btn_0[0], pin_btn_0_lvl};
  assign d_btn[0] = hs_btn_0[1];
  reg [1:0] hs_btn_1 = 2'b00;
  always @(posedge clk_10m) hs_btn_1 <= {hs_btn_1[0], pin_btn_1_lvl};
  assign d_btn[1] = hs_btn_1[1];
  reg [1:0] hs_btn_2 = 2'b00;
  always @(posedge clk_10m) hs_btn_2 <= {hs_btn_2[0], pin_btn_2_lvl};
  assign d_btn[2] = hs_btn_2[1];
  reg [1:0] hs_btn_3 = 2'b00;
  always @(posedge clk_10m) hs_btn_3 <= {hs_btn_3[0], pin_btn_3_lvl};
  assign d_btn[3] = hs_btn_3[1];
  wire [7:0] d_led;
  assign pin_led_0 = ~d_led[0];
  assign pin_led_1 = d_led[1];
  assign pin_led_2 = d_led[2];
  assign pin_led_3 = d_led[3];
  assign pin_led_4 = d_led[4];
  assign pin_led_5 = d_led[5];
  assign pin_led_6 = d_led[6];
  assign pin_led_7 = d_led[7];
  lights u_design (
    .clk_sys(clk_10m),
    .rst(rst),
    .sw(d_sw),
    .btn(d_btn),
    .led(d_led)
  );
  // HIL bridge (hdl/hil/weft_hil.v): reports these outputs and drives the inputs above
  wire [7:0] hil_outs;
  assign hil_outs[0] = d_led[0];  // led:0
  assign hil_outs[1] = d_led[1];  // led:1
  assign hil_outs[2] = d_led[2];  // led:2
  assign hil_outs[3] = d_led[3];  // led:3
  assign hil_outs[4] = d_led[4];  // led:4
  assign hil_outs[5] = d_led[5];  // led:5
  assign hil_outs[6] = d_led[6];  // led:6
  assign hil_outs[7] = d_led[7];  // led:7
  weft_hil #(.CLK_HZ(10000000), .BAUD(115200), .NOUT(8), .NIN(5)) u_hil (
    .clk(clk_10m),
    .rst(rst_cfg),
    .outs(hil_outs),
    .vins(hil_vins),
    .ovr(hil_ovr),
    .dut_rst(hil_rst),
    .tx(pin_uart_tx),
    .rx(pin_uart_rx)
  );
endmodule
